/** wire-formats §i.2 (health-1.json). Current status, not the SLI. `web_ingest` follows the availability definition of C-78: a probe round is good when at least one of the two ingest hostnames accepts a canary event within 2 s (one retry), by 2-of-3 quorum of the probe sources (C-30); `down` when the last round failed, `degraded` when it passed but a hostname or an edge node failed. Per-hostname and per-edge-node status is listed so a dead node or a lost domain is visible. */
export type Health = {
  schema: "scf-analytics/health/1";
  /** worst component */
  status: "ok" | "degraded" | "down";
  checked_at: string;
  version: string;
  components: {
    web_ingest: "ok" | "degraded" | "down";
    otlp_ingest: "ok" | "degraded" | "down";
    dashboards: "ok" | "degraded" | "down";
    processing: "ok" | "degraded" | "down";
  };
  ingest_hostnames: ({
    host: string;
    status: "ok" | "down";
  })[];
  edge_nodes: ({
    /** e.g. edge-a1 */
    node: string;
    status: "ok" | "down" | "draining";
  })[];
  /** last hour, accepted → visible */
  freshness_p99_seconds?: number | null;
  status_page?: string;
};

