/** Tenant's own counters; not rounded (own data, C-39). Events refused because the site was over its daily quota or rate limit appear in `drops` (C-80, C-90). */
export type InstallationCheck = {
  site_id: string;
  /** inclusive (C-86) */
  start: string;
  /** exclusive (C-86) */
  end: string;
  tracker_version_seen?: string | null;
  verdicts: {
    verified: number;
    suspect: number;
    rejected: number;
  };
  reasons: ({
    /** wire-formats §h.2 */
    code: string;
    verdict: "suspect" | "rejected" | "counter";
    count: number;
  })[];
  drops: {
    label: string;
    count: number;
  }[];
  outdated_tracker?: boolean;
  /** page views over the range whose page had the Stellar Wallets Kit present (`standard` profile only); a per-site daily counter kept by the gateway, not an event and not forwarded to the engine (C-93, C-75) */
  kit_present_pageviews: number;
  /** The site's multiplicity mode (C-124, wire-formats §b.4). In `shadow` the edge does not add the reason `multiplicity_high`; `high_shadow` counts the events over the range that met it and were left unchanged. */
  multiplicity: {
    /** effective mode */
    mode: "enforce" | "shadow";
    /** `site`: an SCF operator set an override for this site; `platform`: the platform setting */
    source: "site" | "platform";
    high_shadow: number;
  };
};

