/** Web totals of a site, tenant or the ecosystem, returned as they are — no minimum count, rounding or suppression (C-91). `pageviews`, `pageviews_unidentified` and `visitors_sum` follow the requested `variant`; the visit metrics are one figure each, the same for both variants (C-73). Composable base: open here; closed (`unevaluatedProperties: false`) wherever it is used. */
export type OpWebCells = {
  /** exact total, not thresholded or rounded (C-91); per `variant`, including page views without an identifier */
  pageviews: number;
  /** exact total, not thresholded or rounded (C-91); per `variant`, twin website (C-73) */
  pageviews_unidentified: number;
  /** exact total, not thresholded or rounded (C-91); per `variant`, sum of per-site daily unique visitors */
  visitors_sum: number;
  /** exact total, not thresholded or rounded (C-91); one figure for both variants (C-73) */
  visits: number;
  /** exact total, not thresholded or rounded (C-91); one figure for both variants (C-73) */
  bounces: number;
  /** null when there are no visits */
  bounce_rate_pct: number | null;
  /** session duration; null when there are no visits */
  avg_visit_duration_s: number | null;
  /** share of page views tagged `s`; null without page views */
  suspect_pageview_share: number | null;
};

