/** Breakdown rows carry the minimum count and rounding (C-91): rows below the minimum count are omitted; sums over days are added unrounded and rounded once (C-89). How many values were withheld is reported only in groups of at least `hidden_rows_min` (K1); the control plane always sends the four `hidden_*` fields (optional in this schema so older clients and fixtures stay valid). */
export type OperatorBreakdown = {
  privacy: PrivacyEcho;
  dimension: string;
  rows: ({
    tenant_id: string;
    value: string;
    /** rounded to the rounding step; rows below the minimum count are omitted (C-95); `events` null for non-event dimensions */
    visitors_sum?: number | null;
    /** rounded to the rounding step; rows below the minimum count are omitted (C-95); `events` null for non-event dimensions */
    pageviews?: number | null;
    /** rounded to the rounding step; rows below the minimum count are omitted (C-95); `events` null for non-event dimensions */
    events?: number | null;
  })[];
  /** Values withheld by the minimum count, summed over the tenants for which at least `hidden_rows_min` values were withheld; null when no tenant reaches that. A tenant with fewer withheld values (also none) is not counted, so 0 and 1 cannot be told apart and no total minus the shown rows isolates one withheld value (the suppressed-cohort rule, C-136/C-137). Values cut by `limit` are not withheld and not counted. */
  hidden_rows?: number | null;
  /** the setting `cohort_min_tenants` (≥ 2) applied to `hidden_rows` */
  hidden_rows_min?: number;
  /** the withheld values and their total are never returned (C-95) */
  hidden_total_suppressed?: true;
  /** the tenants counted in `hidden_rows`, each with at least `hidden_rows_min` withheld values */
  hidden_by_tenant?: {
    tenant_id: string;
    hidden_rows: number;
  }[];
};

