/** RFC 9457 problem details (`application/problem+json`). `code` is from the closed catalogue `ProblemCode`. */
export type Problem = {
  /** https://<portal>.<domain-a>/problems/<code> */
  type: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  code?: ProblemCode;
  request_id?: string;
  errors?: {
    /** JSON Pointer into the request */
    pointer: string;
    detail: string;
  }[];
};

/** Closed catalogue of RFC 9457 `code` values, identical in `control-plane.openapi.yaml` and `operator-metrics.openapi.yaml` (CR-25). HTTP status per code: `validation_failed` 400 — request parameters or body invalid; `errors` lists JSON Pointers; `unauthenticated` 401 — no valid session, or a missing, malformed, unknown, expired or revoked key; `forbidden` 403 — role or scope missing; `csrf_failed` 403 — state-changing request without a matching `Origin` or the `X-SCF-Request` header; `step_up_required` 403 — SCF-operator passkey assertion older than 10 minutes (`x-requires-step-up`, C-09); `recent_auth_required` 403 — tenant member's sign-in older than 10 minutes (`x-requires-recent-auth`, C-87); `not_found` 404 — unknown identifier, or one that belongs to another tenant (indistinguishable, C-87); `not_acceptable` 406 — unsupported `Accept` type; `conflict` 409 — state conflict or uniqueness violation (constraint names are never echoed); `quota_exceeded` 409 — tenant or site quota reached (sites, services, tokens, …); `precondition_failed` 412 — `If-Match` / `If-None-Match` precondition failed; `unprocessable` 422 — semantically invalid, e.g. a verification that failed; `rate_limited` 429 — rate limit exceeded; see `Retry-After`; `internal_error` 500 — unexpected server error (no internal detail echoed); `not_implemented` 501 — operation not built yet (temporary during the build; none may remain at gate G4, C-113); `unavailable` 503 — temporarily unavailable (read-only database fallback or engine down); see `Retry-After`. */
export type ProblemCode = "validation_failed" | "unauthenticated" | "forbidden" | "csrf_failed" | "step_up_required" | "recent_auth_required" | "not_found" | "not_acceptable" | "conflict" | "quota_exceeded" | "precondition_failed" | "unprocessable" | "rate_limited" | "internal_error" | "not_implemented" | "unavailable";

export type ProtocolId = "blend" | "soroswap" | "defindex" | "aquarius" | "reflector";

