export type VerificationLevel = "L0" | "L1" | "L2" | "L3" | "L4";

export type VerificationOption = {
  method: "dns_txt" | "well_known" | "meta_tag" | "stellar_toml_account" | "operator_approval";
  available: boolean;
  detail: string;
};

export type VerificationStatus = {
  level: VerificationLevel;
  evidence: Evidence[];
  registry_links: RegistryLink[];
  next_steps?: ("verify_domain" | "link_stellar_account" | "await_registry_match" | "await_operator_approval")[];
};

export type VerifierKeys = {
  schema: "usagemap/verifier-keys/1";
  generated_at: string;
  snapshot_signing: {
    alg: "Ed25519";
    jwks_url: string;
    keys: ({
      kid: string;
      x: string;
      stellar_public_key: string;
      not_before: string | null;
      not_after: string | null;
      current: boolean;
    })[];
  };
  seal: {
    network: SealNetwork;
    accounts: string[];
    seals_url: string;
    audit_anchor_url_template: string;
    latest_confirmed: (null | {
      day: string;
      ledger: number;
      tx_hash: string;
      explorer_url: string | null;
    });
  };
  sep10: (null | {
    home_domain: string;
    signing_key: string;
  });
  links: {
    self: string;
    stellar_toml: string;
    verify_page: string;
  };
  statement: string;
};

/** C-136: Stellar event schema v1 counts (wire-formats §a.3.1). `steps` in funnel order; `by_wallet` per wallet type for the events that carry one. */
export type WalletFunnel = {
  range: {
    start: string;
    end: string;
  };
  network: "mainnet" | "testnet" | "futurenet" | "local" | "all";
  variant: "verified" | "raw";
  schema: "scf-stellar-events/1";
  steps: ({
    event: "wallet_modal_opened" | "wallet_modal_closed" | "wallet_selected" | "wallet_connect" | "wallet_disconnect" | "sign_requested" | "sign_approved" | "sign_rejected" | "tx_submitted" | "smart_wallet_created" | "passkey_used";
    count: number;
    by_wallet: {
      [key: string]: number;
    };
    /** other properties of the event: key → value → count (connect_kind, sign_kind, error_class, result_class, duration, outcome, passkey_op) */
    by_property: {
      [key: string]: {
        [key: string]: number;
      };
    };
  })[];
  daily: {
    day: string;
    wallet_connect: number;
    sign_approved: number;
    tx_submitted_success: number;
  }[];
};

/** PublicKeyCredentialCreationOptionsJSON / RequestOptionsJSON as produced by @simplewebauthn/server; challenge single-use, 5 min. */
export type WebAuthnOptions = {
  [key: string]: unknown;
};

/** RegistrationResponseJSON / AuthenticationResponseJSON from the browser. */
export type WebAuthnResponse = {
  [key: string]: unknown;
};

/** Breakdown rows per variant (verified/raw). Visits are not broken down by variant (C-73). */
export type WebBreakdown = {
  range: RangeEcho;
  dimension: "referrer" | "country" | "device" | "browser" | "os" | "path" | "event";
  verified?: BreakdownRow[];
  raw?: BreakdownRow[];
  /** true when served from aggregates, which keep only the top 50 rows per day; the remainder is in the `is_other` row */
  truncated?: boolean;
};

export type WebFunnelReport = {
  range: ReportRange;
  variant: "verified" | "raw";
  window_minutes: number;
  steps: ({
    type: "path" | "event";
    value: string;
    /** visitors who reached this step in order; null when suppressed */
    visitors: number | null;
    /** visitors of this step as a share of the first step's, one decimal */
    conversion_pct: number | null;
    /** visitors of this step as a share of the previous step's, one decimal (null for the first step) */
    step_conversion_pct: number | null;
    /** below the minimum count with `anonymous_reports` (C-51) */
    suppressed: boolean;
  })[];
};

export type WebGoalsReport = {
  range: ReportRange;
  variant: "verified" | "raw";
  /** visitors with any event in the range (the denominator); null when suppressed */
  total_visitors: number | null;
  goals: ({
    type: "path" | "event";
    value: string;
    visitors: number | null;
    /** `visitors` ÷ `total_visitors`, one decimal */
    conversion_pct: number | null;
    suppressed: boolean;
  })[];
};

export type WebJourneyReport = {
  range: ReportRange;
  variant: "verified" | "raw";
  steps: number;
  /** sequences followed by fewer visits are left out (setting `tenant_min_count`) */
  min_count: number;
  journeys: {
    items: ReportStep[];
    /** visits that followed this sequence (rounded with `anonymous_reports`) */
    visits: number;
  }[];
  /** visits of the sequences left out by the minimum count */
  other_visits: number;
  /** number of sequences left out by the minimum count */
  suppressed_journeys: number;
};

/** One bucket of verified or raw counts (fields per `metrics`). */
export type WebPoint = {
  /** bucket start */
  t: string;
  pageviews?: number;
  pageviews_unidentified?: number;
  visitors?: number;
};

/** null ratios sort last; `pageviews_change` needs `compare=previous` (else 400) */
export type WebSort = "pageviews" | "-pageviews" | "visitors_sum" | "-visitors_sum" | "visits" | "-visits" | "bounce_rate_pct" | "-bounce_rate_pct" | "avg_visit_duration_s" | "-avg_visit_duration_s" | "trust_score_28d" | "-trust_score_28d" | "pageviews_change" | "-pageviews_change" | "name";

/** Page views and unique visitors as `verified` and/or `raw` (per `variant`); visits, bounce rate and session duration once, in `visit_metrics` (C-73). */
export type WebStats = {
  range: RangeEcho;
  verified?: WebTotals;
  raw?: WebTotals;
  visit_metrics: WebVisitMetrics;
  /** with compare=previous: the same figures for the preceding range of equal length, composed by the same live/rollup rules as the main range (C-112); `null` with `comparison_unavailable` = true when that range cannot be composed (for example its rollup part is not whole UTC days) */
  previous?: {
    verified?: WebTotals;
    raw?: WebTotals;
    visit_metrics: WebVisitMetrics;
  } | null;
  /** true when compare=previous was requested but the preceding range could not be composed by the live/rollup rules (C-112); `previous` is then `null` */
  comparison_unavailable?: boolean;
};

export type WebTimeseries = {
  range: RangeEcho;
  unit: "hour" | "day" | "month";
  verified?: WebPoint[];
  raw?: WebPoint[];
  visit_metrics?: WebVisitPoint[];
};

/** Counts that exist as verified and raw (C-73). Page views: verified = tag `v` in the main and the twin website; raw = all events of both. Unique visitors: verified = sessions with at least one verified event; raw = all sessions of the main website. */
export type WebTotals = {
  /** verified: events tagged `v` in the main and the twin website; raw: all events of both (C-73); includes the page views without an identifier */
  pageviews: number;
  /** page views without a visitor identifier (twin website), reported separately; verified (tag `v`) and raw (all) by the same rule as `pageviews` */
  pageviews_unidentified: number;
  /** unique visitors over the range — exact; over several days the sum of daily unique visitors, because the visitor key rotates at 00:00 UTC and no visitor is recognised across days (ADR-0007, C-110) */
  visitors: number;
};

/** Visit-based metrics, one figure each (C-73): computed by the engine over all identified, non-rejected events in a single query; there is no verified-only variant. A visit with any custom or wallet event is not a bounce (C-75). */
export type WebVisitMetrics = {
  visits: number;
  bounces: number;
  bounce_rate_pct: number | null;
  /** session duration */
  avg_visit_duration_s: number | null;
  /** share of the range's page views tagged `s` (suspect); null without page views */
  suspect_pageview_share: number | null;
};

/** One bucket of visit metrics, one figure each (C-73; fields per `metrics`). A bucket is a day or a month, never an hour (C-112): complete days from `web_daily_totals`, the current day from a live engine call (or today's rollup when the engine does not answer within 5 s, `range.partial_today`). */
export type WebVisitPoint = {
  /** bucket start */
  t: string;
  visits?: number;
  bounces?: number;
  bounce_rate_pct?: number | null;
  avg_visit_duration_s?: number | null;
  suspect_pageview_share?: number | null;
};

